#include <stdio.h>
#include <string.h>

int is_allowed(const char *role) {
    FILE *f = fopen("allowed_roles.txt", "r");
    if (!f) return 0;
    char buf[256];
    if (!fgets(buf, sizeof(buf), f)) { fclose(f); return 0; }
    fclose(f);
    char *tok = strtok(buf, ",\n");
    while (tok) {
        while (*tok == ' ') tok++;
        if (strcmp(tok, role) == 0) return 1;
        tok = strtok(NULL, ",\n");
    }
    return 0;
}

